    zh: "经验证的开放数据集登记库，用于揭露腐败、绘制冲突地图、记录人权侵害。每个来源均免费、按国家索引，因其证据价值而被选入。",
    ja: "腐敗の暴露、紛争の可視化、人権侵害の記録のための、精査されたオープンデータセット・レジストリ。各ソースは無料で、国別に索引化されている。",
    ko: "부패 폭로, 분쟁 매핑, 인권 침해 기록을 위한 검증된 오픈 데이터셋 등록부. 모든 출처는 무료이며 국가별로 색인됩니다.",
