  "home.6_eq_sub": { en: "// hunger is the proof of concept. every solvable crisis costs less than military spending.", pt: "// a fome é a prova de conceito. toda crise resolvível custa menos que o gasto militar.", es: "// el hambre es la prueba de concepto. toda crisis resoluble cuesta menos que el gasto militar.", fr: "// la faim est la preuve de concept. chaque crise résolvable coûte moins que les dépenses militaires.", zh: "// 饥饿是概念验证。每一个可解决的危机成本都低于军费开支。", ja: "// 飢餓は概念実証である。解決可能な危機はすべて軍事費より安い。", ko: "// 기아는 개념 증명이다. 해결 가능한 모든 위기는 군사비 지출보다 적다.", hi: "// भूख अवधारणा का प्रमाण है। हल करने योग्य हर संकट सैन्य खर्च से सस्ता है।", ar: "// الجوع هو دليل المفهوم. كل أزمة قابلة للحل تكلف أقل من الإنفاق العسكري.", ru: "// голод — доказательство концепции. каждый решаемый кризис обходится дешевле военных расходов." },
