  "eq.adjust_slider": { en: "Adjust the slider to see how different annual investments change the hunger trajectory (2025-2034)", pt: "Ajuste o controle para ver como diferentes investimentos anuais mudam a trajetória da fome (2025-2034)", es: "Ajusta el control para ver cómo diferentes inversiones anuales cambian la trayectoria del hambre (2025-2034)", fr: "Ajustez le curseur pour voir comment différents investissements annuels changent la trajectoire de la faim (2025-2034)", zh: "调整滑块查看不同年度投资如何改变饥饿轨迹（2025-2034）", ja: "スライダーを調整して、年間投資が飢餓の軌跡をどう変えるか確認（2025-2034）", ko: "슬라이더를 조정하여 연간 투자가 기아 궤적을 어떻게 바꾸는지 확인 (2025-2034)", hi: "स्लाइडर समायोजित करें और देखें कि विभिन्न वार्षिक निवेश भूख प्रक्षेपपथ को कैसे बदलते हैं (2025-2034)", ar: "اضبط الشريط التمريري لترى كيف تغير الاستثمارات السنوية المختلفة مسار الجوع (2025-2034)", ru: "Настройте ползунок, чтобы увидеть, как разные годовые инвестиции меняют траекторию голода (2025-2034)" },
  "eq.final_hunger": { en: "FINAL HUNGER (2034)", pt: "FOME FINAL (2034)", es: "HAMBRE FINAL (2034)", fr: "FAIM FINALE (2034)", zh: "最终饥饿（2034）", ja: "最終飢餓（2034）", ko: "최종 기아 (2034)", hi: "अंतिम भूख (2034)", ar: "الجوع النهائي (2034)", ru: "ИТОГОВЫЙ ГОЛОД (2034)" },
