  "eq.not_achieved": { en: "NOT ACHIEVED", pt: "NÃO ALCANÇADO", es: "NO ALCANZADO", fr: "NON ATTEINT", zh: "未达成", ja: "未達成", ko: "미달성", hi: "अप्राप्त", ar: "لم يتحقق", ru: "НЕ ДОСТИГНУТО" },
  "eq.deaths_avoided": { en: "DEATHS AVOIDED", pt: "MORTES EVITADAS", es: "MUERTES EVITADAS", fr: "DÉCÈS ÉVITÉS", zh: "避免死亡", ja: "回避された死亡", ko: "방지된 사망", hi: "रोकी गई मौतें", ar: "الوفيات التي تم تجنبها", ru: "ПРЕДОТВРАЩЁННЫЕ СМЕРТИ" },
  "eq.m_people_hungry": { en: "M people hungry", pt: "M de pessoas com fome", es: "M de personas con hambre", fr: "M de personnes affamées", zh: "百万饥饿人口", ja: "百万人の飢餓", ko: "백만 명 기아 인구", hi: "मिलियन भूखे लोग", ar: "مليون شخص جائع", ru: "млн голодающих" },
