  "review.pending_commit": { en: "Committed, not yet revealed. Reveal to count it.", pt: "Comprometida, ainda não revelada. Revele para contá-la.", es: "Comprometida, aún no revelada. Revélala para contarla.", fr: "Engagée, non révélée. Révélez-la pour la compter.", zh: "已提交，尚未揭示。揭示以计入。", ja: "コミット済み・未リビール。リビールしてカウント。", ko: "커밋됨, 아직 리빌 안 됨. 공개해야 집계됩니다.", hi: "कमिट हो चुकी, अभी रिवील नहीं। रिवील करके गिनें।", ar: "مُلتَزَم بها، لم تُظهر بعد. أظهرها لتُحتسب.", ru: "Зафиксировано, не раскрыто. Раскройте, чтобы засчитать." },
  "review.flag_verified": { en: "SEEN VERIFIED EVIDENCE", pt: "VI EVIDÊNCIA VERIFICADA", es: "VI EVIDENCIA VERIFICADA", fr: "PREUVE VÉRIFIÉE VUE", zh: "见过已验证证据", ja: "検証済み証拠を見た", ko: "검증된 증거 봄", hi: "सत्यापित साक्ष्य देखा", ar: "رأيت أدلة موثقة", ru: "ВИДЕЛ ПРОВЕРЕННЫЕ ДОКАЗАТЕЛЬСТВА" },
  "review.flag_sources": { en: "SELF-CORROBORATING SOURCES", pt: "FONTES AUTOCORROBORANTES", es: "FUENTES AUTOCORROBORANTES", fr: "SOURCES AUTOCORROBORANTES", zh: "自证来源", ja: "自己裏付けの情報源", ko: "자기 보강 출처", hi: "स्व-पुष्टि स्रोत", ar: "مصادر ذاتية التأكيد", ru: "САМОПОДТВЕРЖДАЮЩИЕ ИСТОЧНИКИ" },
