  /* ═══════════════════════════════════════════════════════════════
   *  THE RECEIPTS — DATA INTEGRITY SCAN
   * ═══════════════════════════════════════════════════════════════ */
  "receipts.integrity_scan": { en: "DATA INTEGRITY SCAN", pt: "VERIFICAÇÃO DE INTEGRIDADE", es: "ESCANEO DE INTEGRIDAD", fr: "SCAN D'INTÉGRITÉ", zh: "数据完整性扫描", ja: "データ整合性スキャン", ko: "데이터 무결성 검사", hi: "डेटा अखंडता स्कैन", ar: "فحص سلامة البيانات", ru: "СКАН ЦЕЛОСТНОСТИ ДАННЫХ" },
  "receipts.integrity_desc": { en: "Verifies the SHA-256 manifest of this build's public data files. A copy served from any mirror can be audited — tampered data is flagged locally, no network trust required.", pt: "Verifica o manifesto SHA-256 dos arquivos públicos de dados desta build. Qualquer cópia servida de um espelho pode ser auditada — dados adulterados são sinalizados localmente, sem confiança de rede.", es: "Verifica el manifiesto SHA-256 de los archivos de datos públicos de esta compilación. Cualquier copia servida desde un espejo puede auditarse — los datos alterados se señalan localmente, sin confianza de red.", fr: "Vérifie le manifeste SHA-256 des fichiers de données publics de cette build. Toute copie servie depuis un miroir peut être auditée — les données altérées sont signalées localement, sans confiance réseau.", zh: "验证此构建公共数据文件的SHA-256清单。来自任何镜像的副本都可审计 — 被篡改的数据会在本地标记，无需网络信任。", ja: "このビルドの公開データファイルのSHA-256マニフェストを検証。どのミラーから提供されたコピーも監査可能 — 改ざんデータはローカルで検出。ネットワークへの信頼は不要。", ko: "이 빌드의 공개 데이터 파일 SHA-256 매니페스트를 검증합니다. 어떤 미러에서 제공된 사본도 감사 가능 — 변조된 데이터는 로컬에서 표시됩니다. 네트워크 신뢰 불필요.", hi: "इस बिल्ड की सार्वजनिक डेटा फ़ाइलों के SHA-256 मैनिफेस्ट को सत्यापित करता है। किसी भी मिरर से परोसी गई प्रति का ऑडिट हो सकता है — छेड़छाड़ किया डेटा स्थानीय रूप से चिह्नित होता है, नेटवर्क पर भरोसा नहीं।", ar: "يتحقق من قائمة SHA-256 لملفات البيانات العامة لهذا البناء. يمكن تدقيق أي نسخة من أي مرآة — البيانات المعدلة تُعلَّم محلياً دون ثقة شبكة.", ru: "Проверяет SHA-256-манифест публичных файлов данных этой сборки. Любая копия с любого зеркала может быть проверена — подделанные данные помечаются локально, без сетевого доверия." },
  "receipts.scan_btn": { en: "[ RUN SCAN ]", pt: "[ EXECUTAR VERIFICAÇÃO ]", es: "[ EJECUTAR ESCANEO ]", fr: "[ LANCER LE SCAN ]", zh: "[ 运行扫描 ]", ja: "[ スキャン実行 ]", ko: "[ 스캔 실행 ]", hi: "[ स्कैन चलाएँ ]", ar: "[ تشغيل الفحص ]", ru: "[ ЗАПУСТИТЬ СКАН ]" },
  "receipts.scanning": { en: "SCANNING...", pt: "VERIFICANDO...", es: "ESCANEANDO...", fr: "SCAN EN COURS...", zh: "扫描中...", ja: "スキャン中...", ko: "스캔 중...", hi: "स्कैन हो रहा है...", ar: "جارٍ الفحص...", ru: "СКАНИРОВАНИЕ..." },
  "receipts.root_match": { en: "ROOT HASH MATCHES PUBLISHED MANIFEST", pt: "HASH RAIZ CORRESPONDE AO MANIFESTO", es: "HASH RAÍZ COINCIDE CON EL MANIFIESTO", fr: "HASH RACINE CORRESPOND AU MANIFESTE", zh: "根哈希与已发布清单一致", ja: "ルートハッシュは公開マニフェストと一致", ko: "루트 해시가 게시된 매니페스트와 일치", hi: "रूट हैश प्रकाशित मैनिफेस्ट से मेल खाता है", ar: "هاش الجذر يطابق المانيفست المنشور", ru: "КОРНЕВОЙ ХЭШ СОВПАДАЕТ С ОПУБЛИКОВАННЫМ" },
  "receipts.root_mismatch": { en: "✗ ROOT HASH MISMATCH — this copy's data files were altered", pt: "✗ HASH RAIZ DIVERGENTE — os dados desta cópia foram alterados", es: "✗ HASH RAÍZ INCORRECTO — los datos de esta copia fueron alterados", fr: "✗ HASH RACINE INCORRECT — les données de cette copie ont été altérées", zh: "✗ 根哈希不匹配 — 此副本的数据文件被篡改", ja: "✗ ルートハッシュ不一致 — このコピーのデータが改ざん", ko: "✗ 루트 해시 불일치 — 이 사본의 데이터 파일이 변조됨", hi: "✗ रूट हैश असंगत — इस प्रति की डेटा फ़ाइलें बदली गईं", ar: "✗ عدم تطابق هاش الجذر — تم تعديل ملفات بيانات هذه النسخة", ru: "✗ КОРНЕВОЙ ХЭШ НЕ СОВПАДАЕТ — данные этой копии изменены" },
  "receipts.files_ok": { en: "files verified", pt: "arquivos verificados", es: "archivos verificados", fr: "fichiers vérifiés", zh: "已验证文件", ja: "検証済みファイル", ko: "검증된 파일", hi: "सत्यापित फ़ाइलें", ar: "ملفات موثقة", ru: "файлов проверено" },
  "receipts.files_failed": { en: "files failed verification", pt: "arquivos reprovados", es: "archivos con errores", fr: "fichiers en échec", zh: "验证失败的文件", ja: "検証失敗ファイル", ko: "검증 실패 파일", hi: "असफल फ़ाइलें", ar: "ملفات فشل التحقق", ru: "файлов не прошло проверку" },

