  "trail.title": { en: "THE TRAIL", pt: "A TRILHA", es: "EL RASTRO", fr: "LA PISTE", zh: "踪迹", ja: "トレイル", ko: "흔적", hi: "पगडंडी", ar: "المسار", ru: "СЛЕД" },
  "trail.section_label": { en: "[06] THE TRAIL", pt: "[06] A TRILHA", es: "[06] EL RASTRO", fr: "[06] LA PISTE", zh: "[06] 踪迹", ja: "[06] トレイル", ko: "[06] 흔적", hi: "[06] पगडंडी", ar: "[06] المسار", ru: "[06] СЛЕД" },
  "trail.entries": { en: "ENTRIES", pt: "REGISTROS", es: "ENTRADAS", fr: "ENTRÉES", zh: "条目", ja: "エントリー", ko: "항목", hi: "प्रविष्टियाँ", ar: "الإدخالات", ru: "ЗАПИСИ" },
  "trail.verified": { en: "VERIFIED", pt: "VERIFICADOS", es: "VERIFICADOS", fr: "VÉRIFIÉS", zh: "已验证", ja: "検証済み", ko: "확인됨", hi: "सत्यापित", ar: "موثقة", ru: "ПРОВЕРЕНО" },
  "trail.total_routed": { en: "TOTAL ROUTED", pt: "TOTAL ROTEADO", es: "TOTAL ENRUTADO", fr: "TOTAL ROUTÉ", zh: "总路由", ja: "ルーティング合計", ko: "총 라우팅", hi: "कुल रूट किए गए", ar: "إجمالي موجه", ru: "ВСЕГО НАПРАВЛЕНО" },
  "trail.create_desc": { en: "Log a resource transfer. Entries are stored locally in your browser (IndexedDB) and persist across sessions.", pt: "Registre uma transferência de recursos. As entradas são armazenadas localmente no seu navegador (IndexedDB) e persistem entre sessões.", es: "Registra una transferencia de recursos. Las entradas se almacenan localmente en tu navegador (IndexedDB) y persisten entre sesiones.", fr: "Enregistrez un transfert de ressources. Les entrées sont stockées localement dans votre navigateur (IndexedDB) et persistent entre les sessions.", zh: "记录资源转移。条目存储在本地浏览器中（IndexedDB），跨会话持久化。", ja: "リソース移転を記録。エントリーはブラウザ（IndexedDB）にローカル保存され、セッション間で永続します。", ko: "자원 이전을 기록하세요. 항목은 브라우저(IndexedDB)에 로컬 저장되며 세션 간 지속됩니다.", hi: "संसाधन स्थानांतरण लॉग करें। प्रविष्टियाँ आपके ब्राउज़र (IndexedDB) में स्थानीय रूप से संग्रहीत हैं और सत्रों में बनी रहती हैं।", ar: "سجّل نقل الموارد. تُخزَّن الإدخالات محلياً في متصفحك (IndexedDB) وتستمر عبر الجلسات.", ru: "Запишите перевод ресурсов. Записи хранятся локально в браузере (IndexedDB) и сохраняются между сессиями." },
  "trail.source_ph": { en: "Source (handle or org)", pt: "Origem (identificador ou org)", es: "Origen (identificador u org)", fr: "Source (pseudo ou org)", zh: "来源（代号或组织）", ja: "送信元（ハンドルまたは組織）", ko: "출처 (핸들 또는 기관)", hi: "स्रोत (हैंडल या संगठन)", ar: "المصدر (معرّف أو مؤسسة)", ru: "Источник (псевдоним или орг)" },
  "trail.destination_ph": { en: "Destination (zone/city)", pt: "Destino (zona/cidade)", es: "Destino (zona/ciudad)", fr: "Destination (zone/ville)", zh: "目的地（区域/城市）", ja: "宛先（地域/都市）", ko: "목적지 (구역/도시)", hi: "गंतव्य (क्षेत्र/शहर)", ar: "الوجهة (منطقة/مدينة)", ru: "Назначение (зона/город)" },
