  "trail.purpose_ph": { en: "Purpose (food, medical...)", pt: "Propósito (comida, médico...)", es: "Propósito (comida, médico...)", fr: "Objet (nourriture, médical...)", zh: "用途（食品、医疗...）", ja: "目的（食料、医療...）", ko: "목적 (식량, 의료...)", hi: "उद्देश्य (भोजन, चिकित्सा...)", ar: "الغرض (طعام، طبي...)", ru: "Назначение (еда, медицина...)" },
