  "trail.entries_stored": { en: "entries stored locally", pt: "registros armazenados localmente", es: "entradas almacenadas localmente", fr: "entrées stockées localement", zh: "条目已本地存储", ja: "エントリーがローカルに保存済み", ko: "항목이 로컬에 저장됨", hi: "प्रविष्टियाँ स्थानीय रूप से संग्रहीत", ar: "إدخالات مخزنة محلياً", ru: "записей сохранено локально" },
