  "mask.title": { en: "THE MASK", pt: "A MÁSCARA", es: "LA MÁSCARA", fr: "LE MASQUE", zh: "面具", ja: "マスク", ko: "가면", hi: "मुखौटा", ar: "القناع", ru: "МАСКА" },
