  "eq.out_of_gdp": { en: "$93B out of ~$105T global GDP", pt: "$93B de ~$105T do PIB global", es: "$93B de ~$105T del PIB global", fr: "$93B sur ~$105T du PIB mondial", zh: "$93B / 约$105T 全球GDP", ja: "$93B / 約$105T 世界GDP", ko: "$93B / 약 $105T 세계 GDP", hi: "$93B / ~$105T वैश्विक जीडीपी", ar: "93 مليار $ من ~105 تريليون $ ناتج محلي عالمي", ru: "$93 млрд из ~$105 трлн мирового ВВП" },
  "eq.out_of_military": { en: "$93B out of $2.4T annual military", pt: "$93B de $2.4T militar anual", es: "$93B de $2.4T militar anual", fr: "$93B sur $2.4T militaire annuel", zh: "$93B / $2.4T 年度军费", ja: "$93B / $2.4T 年間軍事費", ko: "$93B / $2.4T 연간 군사비", hi: "$93B / $2.4T वार्षिक सैन्य", ar: "93 مليار $ من 2.4 تريليون $ إنفاق عسكري سنوي", ru: "$93 млрд из $2.4 трлн годовых военных расходов" },
  "eq.share_stat_1_pre": { en: "Ending global hunger costs $93B/year. World military spending: $2.4T/year. That's ", pt: "Acabar com a fome global custa $93B/ano. Gasto militar mundial: $2.4T/ano. Isso é ", es: "Acabar con el hambre global cuesta $93B/año. Gasto militar mundial: $2.4T/año. Eso es ", fr: "Eradiquer la faim mondiale coûte $93B/an. Dépenses militaires mondiales: $2.4T/an. Soit ", zh: "终结全球饥饿每年花费$93B。世界军费开支：$2.4T/年。这是 ", ja: "世界の飢餓を終わらせるコストは$93B/年。世界の軍事費：$2.4T/年。それは ", ko: "세계 기아 종식 비용은 $93B/년이다. 세계 군사비: $2.4T/년. 이는 ", hi: "वैश्विक भूख समाप्त करने का खर्च $93B/वर्ष है। विश्व सैन्य खर्च: $2.4T/वर्ष। यह है ", ar: "إنهاء الجوع العالمي يكلف 93 مليار $/سنة. الإنفاق العسكري العالمي: 2.4 تريليون $/سنة. هذا ", ru: "Искоренение мирового голода стоит $93 млрд/год. Мировые военные расходы: $2.4 трлн/год. Это " },
  "eq.share_stat_1_post": { en: ". [Source: SIPRI/FAO]", pt: ". [Fonte: SIPRI/FAO]", es: ". [Fuente: SIPRI/FAO]", fr: ". [Source: SIPRI/FAO]", zh: "。[来源：SIPRI/FAO]", ja: "。[出典：SIPRI/FAO]", ko: ". [출처: SIPRI/FAO]", hi: ". [स्रोत: SIPRI/FAO]", ar: ". [المصدر: SIPRI/FAO]", ru: ". [Источник: SIPRI/FAO]" },
  "eq.share_stat_2": { en: "The world spends more on military in 14 days than it would cost to end hunger for a year. [Source: SIPRI/FAO]", pt: "O mundo gasta mais com militar em 14 dias do que custaria acabar com a fome por um ano. [Fonte: SIPRI/FAO]", es: "El mundo gasta más en militar en 14 días de lo que costaría acabar con el hambre por un año. [Fuente: SIPRI/FAO]", fr: "Le monde dépense plus en militaire en 14 jours qu'il n'en coûterait pour éradiquer la faim pendant un an. [Source: SIPRI/FAO]", zh: "世界14天的军费开支超过一年消除饥饿的成本。[来源：SIPRI/FAO]", ja: "世界は14日間の軍事費として、飢餓を1年間終わらせるコスト以上を費やしている。[出典：SIPRI/FAO]", ko: "세계는 14일의 군사비로 1년간 기아를 종식시킬 수 있는 비용보다 더 많이 지출한다. [출처: SIPRI/FAO]", hi: "दुनिया 14 दिनों में सैन्य पर उससे अधिक खर्च करती है जितना एक वर्ष के लिए भूख समाप्त करने में लगेगा। [स्रोत: SIPRI/FAO]", ar: "ينفق العالم على العسكري في 14 يومًا أكثر مما يكلف إنهاء الجوع لمدة عام. [المصدر: SIPRI/FAO]", ru: "Мир тратит на военные нужды за 14 дней больше, чем стоило бы искоренение голода на год. [Источник: SIPRI/FAO]" },
  "eq.share_stat_3_pre": { en: "$93B is just ", pt: "$93B é apenas ", es: "$93B es solo ", fr: "$93B n'est que ", zh: "$93B仅为", ja: "$93Bはわずか", ko: "$93B는 단지 ", hi: "$93B केवल ", ar: "93 مليار $ هي فقط ", ru: "$93 млрд — всего " },
  "eq.share_stat_3_post": { en: " of world GDP. We can afford this 250 times over. [Source: World Bank/FAO]", pt: " do PIB mundial. Podemos pagar isso 250 vezes. [Fonte: Banco Mundial/FAO]", es: " del PIB mundial. Podemos pagar esto 250 veces. [Fuente: Banco Mundial/FAO]", fr: " du PIB mondial. Nous pouvons nous le permettre 250 fois. [Source: Banque mondiale/FAO]", zh: " 的世界GDP。我们可以负担250次。[来源：世界银行/FAO]", ja: " の世界GDP。これは250回分余裕がある。[出典：世界銀行/FAO]", ko: "의 세계 GDP이다. 250배까지 감당할 수 있다. [출처: 세계은행/FAO]", hi: " विश्व जीडीपी है। हम इसे 250 गुना तक वहन कर सकते हैं। [स्रोत: विश्व बैंक/FAO]", ar: " من الناتج المحلي العالمي. يمكننا تحمل هذا 250 مرة. [المصدر: البنك الدولي/FAO]", ru: " мирового ВВП. Мы можем позволить это 250 раз. [Источник: Всемирный банк/FAO]" },
