  "api.subtitle_extra": { en: "No auth. No rate limit. No tracking. Just data.", pt: "Sem autenticação. Sem limite. Sem rastreamento. Só dados.", es: "Sin autenticación. Sin límite. Sin rastreo. Solo datos.", fr: "Sans auth. Sans limite. Sans suivi. Juste des données.", zh: "无需认证。无限制。无追踪。只有数据。", ja: "認証不要。制限なし。追跡なし。データだけ。", ko: "인증 없음. 제한 없음. 추적 없음. 데이터뿐.", hi: "कोई प्रमाणीकरण नहीं। कोई सीमा नहीं। कोई ट्रैकिंग नहीं। केवल डेटा।", ar: "بدون مصادقة. بدون حد. بدون تتبع. بيانات فقط.", ru: "Без авторизации. Без лимитов. Без отслеживания. Только данные." },
