  "sub.ledger_extra": { en: "What's missing is political will. Here's the full accounting.", pt: "Falta vontade política. Aqui está a contabilidade completa.", es: "Falta voluntad política. Aquí está la contabilidad completa.", fr: "Ce qui manque c'est la volonté politique. Voici la comptabilité complète.", zh: "缺少的是政治意愿。这是完整的账目。", ja: "欠けているのは政治的意志。完全な会計報告はここに。", ko: "부족한 것은 정치적 의지. 전체 회계가 여기 있습니다.", hi: "कमी राजनीतिक इच्छाशक्ति की है। पूरा लेखा यहाँ है।", ar: "ما ينقص هو الإرادة السياسية. ها هي المحاسبة الكاملة.", ru: "Не хватает политической воли. Вот полный отчёт." },
  "sub.stories_extra": { en: "the problem → the people → the solution → the action. crisis timelines show how we got here.", pt: "o problema → as pessoas → a solução → a ação. cronogramas de crise mostram como chegamos aqui.", es: "el problema → la gente → la solución → la acción. las cronologías de crisis muestran cómo llegamos aquí.", fr: "le problème → les gens → la solution → l'action. les chronologies de crise montrent comment nous en sommes arrivés là.", zh: "问题 → 人民 → 解决方案 → 行动。危机时间线展示我们如何走到这一步。", ja: "問題 → 人々 → 解決策 → 行動。危機のタイムラインが私たちがどうやってここに来たかを示す。", ko: "문제 → 사람들 → 해결책 → 행동. 위기 타임라인이 우리가 어떻게 여기에 왔는지 보여준다.", hi: "समस्या → लोग → समाधान → कार्रवाई। संकट समयरेखा दिखाती है कि हम यहाँ कैसे पहुँचे।", ar: "المشكلة → الناس → الحل → العمل. الجداول الزمنية للأزمات تظهر كيف وصلنا إلى هنا.", ru: "проблема → люди → решение → действие. хроники кризисов показывают, как мы сюда пришли." },
  "sub.lens_extra": { en: "Compare countries. Find patterns. Make arguments.", pt: "Compare países. Encontre padrões. Construa argumentos.", es: "Compara países. Encuentra patrones. Construye argumentos.", fr: "Comparez les pays. Trouvez des modèles. Construisiez des arguments.", zh: "比较国家。发现规律。构建论点。", ja: "国を比較。パターンを見つける。議論を構築する。", ko: "국가를 비교하라. 패턴을 찾아라. 주장을 펼쳐라.", hi: "देशों की तुलना करें। पैटर्न खोजें। तर्क बनाएं।", ar: "قارن الدول. اكتشف الأنماط. ابنِ الحجج.", ru: "Сравнивайте страны. Находите закономерности. Стройте аргументы." },
  "sub.briefing_extra": { en: "Print it. Share it. Make the argument undeniable.", pt: "Imprima. Compartilhe. Torne o argumento irrefutável.", es: "Imprímelo. Compártelo. Haz el argumento irrefutable.", fr: "Imprimez-le. Partagez-le. Rendez l'argument irréfutable.", zh: "打印它。分享它。让论点无可辩驳。", ja: "印刷して。共有して。議論を否定できないものに。", ko: "인쇄하라. 공유하라. 주장을 부정할 수 없게 만들어라.", hi: "प्रिंट करें। साझा करें। तर्क को अकाट्य बनाएं।", ar: "اطبعه. شاركه. اجعل الحجة لا تقبل الجدل.", ru: "Распечатайте. Поделитесь. Сделайте аргумент неоспоримым." },
  "sub.choice_extra": { en: "countries spend more on military than health.", pt: "países gastam mais com militar do que saúde.", es: "países gastan más en militar que en salud.", fr: "pays dépensent plus en militaire qu'en santé.", zh: "国家在军事上的支出超过健康。", ja: "国は健康より軍事により多く費やす。", ko: "국가들은 건강보다 군사에 더 많이 지출한다.", hi: "देश स्वास्थ्य से अधिक सैन्य पर खर्च करते हैं।", ar: "الدول تنفق على العسكرية أكثر من الصحة.", ru: "стран тратят на военных больше чем на здоровье." },
  "sub.tactics_extra": { en: "succeeds 53% of the time. Armed insurgency: 26%. The data is clear.", pt: "sucede 53% das vezes. Insurgência armada: 26%. Os dados são claros.", es: "triunfa el 53% de las veces. Insurgencia armada: 26%. Los datos son claros.", fr: "réussit 53% du temps. Insurrection armée: 26%. Les données sont claires.", zh: "成功率53%。武装叛乱：26%。数据很清楚。", ja: "53%の成功率。武装反乱：26%。データは明確だ。", ko: "53% 성공. 무장 봉기: 26%. 데이터가 명확하다.", hi: "53% सफलता। सशस्त्र विद्रोह: 26%। डेटा स्पष्ट है।", ar: "ينجح 53% من الوقت. التمرد المسلح: 26%. البيانات واضحة.", ru: "добивается успеха в 53% случаев. Вооружённое восстание: 26%. Данные ясны." },
