  "fronts.tag": { en: "[19] THE FRONTS", pt: "[19] AS FRENTE", es: "[19] LOS FRENTES", fr: "[19] LES FRONTS", zh: "[19] 各战线", ja: "[19] 各戦線", ko: "[19] 전선들", hi: "[19] मोर्चे", ar: "[19] الجبهات", ru: "[19] ФРОНТЫ" },
