  "fronts.subtitle": { en: "// The crisis is not distributed evenly. Africa holds 68% of the world's hunger hotspots. Here is where each front stands.", pt: "// A crise não é distribuída uniformemente. A África concentra 68% dos hotspots de fome do mundo. Veja onde cada frente está.", es: "// La crisis no se distribuye uniformemente. África tiene el 68% de los puntos críticos de hambre del mundo. Aquí está el estado de cada frente.", fr: "// La crise n'est pas répartie uniformément. L'Afrique concentre 68% des points chauds de la faim dans le monde. Voici où en est chaque front.", zh: "// 危机分布不均。非洲拥有世界68%的饥饿热点。这里是各战线的状况。", ja: "// 危機は均等に分布していない。アフリカは世界の飢餓ホットスポットの68%を占める。各戦線の現状はこちら。", ko: "// 위기는 균등하게 분포하지 않는다. 아프리카가 세계 기아 핫스팟의 68%를 차지한다. 각 전선의 현황은 여기 있다.", hi: "// संकट समान रूप से वितरित नहीं है। अफ्रीका में दुनिया के 68% भूख हॉटस्पॉट हैं। यहाँ प्रत्येक मोर्चे की स्थिति है।", ar: "// الأزمة لا تتوزع بالتساوي. أفريقيا تحوي 68% من بؤر الجوع في العالم. هنا موقف كل جبهة.", ru: "// Кризис распределён неравномерно. Африка содержит 68% мировых очагов голода. Вот положение каждого фронта." },
  "fronts.avg_vulnerability": { en: "AVG VULNERABILITY", pt: "VULNERABILIDADE MÉDIA", es: "VULNERABILIDAD MEDIA", fr: "VULNÉRABILITÉ MOY.", zh: "平均脆弱性", ja: "平均脆弱性", ko: "평균 취약성", hi: "औसत भेद्यता", ar: "متوسط الهشاشة", ru: "СРЕДН. УЯЗВИМОСТЬ" },
