  "fronts.overlay_desc": { en: "// Vulnerability scores overlaid. Africa is in a category of its own.", pt: "// Pontuações de vulnerabilidade sobrepostas. A África está numa categoria própria.", es: "// Puntuaciones de vulnerabilidad superpuestas. África está en una categoría propia.", fr: "// Scores de vulnérabilité superposés. L'Afrique est dans une catégorie à part.", zh: "// 脆弱性评分叠加。非洲独树一帜。", ja: "// 脆弱性スコアを重ね合わせ。アフリカは独自のカテゴリー。", ko: "// 취약성 점수 겹침. 아프리카는 독자적인 범주다.", hi: "// भेद्यता स्कोर अध्यारोपित। अफ्रीका अपनी अलग श्रेणी में है।", ar: "// درجات الهشاشة متراكبة. أفريقيا في فئة منفردة.", ru: "// Очки уязвимости наложены. Африка — вне конкуренции." },
