  "timeline.link_allocator": { en: "▶ ALLOCATE THE BUDGET", pt: "▶ ALOCAR O ORÇAMENTO", es: "▶ ASIGNAR EL PRESUPUESTO", fr: "▶ ALLOUER LE BUDGET", zh: "▶ 分配预算", ja: "▶ 予算を配分", ko: "▶ 예산 배분", hi: "▶ बजट आवंटित करें", ar: "▶ تخصيص الميزانية", ru: "▶ РАСПРЕДЕЛИТЬ БЮДЖЕТ" },
