  "timeline.m_people": { en: "M people", pt: "M pessoas", es: "M personas", fr: "M personnes", zh: "百万人", ja: "百万人", ko: "백만 명", hi: "मिलियन लोग", ar: "مليون نسمة", ru: "млн людей" },
  "timeline.lives_saved_cumul_axis": { en: "Lives saved (cumulative)", pt: "Vidas salvas (acumuladas)", es: "Vidas salvadas (acumuladas)", fr: "Vies sauvées (cumulées)", zh: "拯救生命（累计）", ja: "救われた命（累計）", ko: "구조된 생명 (누적)", hi: "बचाई गई जानें (संचयी)", ar: "أرواح ناجية (تراكمي)", ru: "Спасено жизней (всего)" },
  "timeline.lives_saved": { en: "Lives saved", pt: "Vidas salvas", es: "Vidas salvadas", fr: "Vies sauvées", zh: "拯救生命", ja: "救われた命", ko: "구조된 생명", hi: "बचाई गई जानें", ar: "أرواح ناجية", ru: "Спасено жизней" },
  "timeline.m_hungry": { en: "M hungry", pt: "M com fome", es: "M hambrientos", fr: "M affamés", zh: "百万人饥饿", ja: "百万人飢餓", ko: "백만 명 굶주림", hi: "मिलियन भूखे", ar: "مليون جائع", ru: "млн голодных" },
