  /* ═══════════════════════════════════════════════════════════════
   *  THE ACT
   * ═══════════════════════════════════════════════════════════════ */
  "act.tag": { en: "[12] THE ACT", pt: "[12] O ATO", es: "[12] EL ACTO", fr: "[12] L'ACTE", zh: "[12] 行动", ja: "[12] 行動", ko: "[12] 행동", hi: "[12] कार्रवाई", ar: "[12] العمل", ru: "[12] ДЕЙСТВИЕ" },
  "act.title": { en: "THE ACT", pt: "O ATO", es: "EL ACTO", fr: "L'ACTE", zh: "行动", ja: "行動", ko: "행동", hi: "कार्रवाई", ar: "العمل", ru: "ДЕЙСТВИЕ" },
  "act.subtitle_extra": { en: "Tweet threads, WhatsApp messages, Instagram captions — all pre-written with real data. Copy. Paste. Change the narrative.", pt: "Tópicos de tweet, mensagens de WhatsApp, legendas de Instagram — tudo pré-escrito com dados reais. Copie. Cole. Mude a narrativa.", es: "Hilos de tweet, mensajes de WhatsApp, captions de Instagram — todo preescrito con datos reales. Copia. Pega. Cambia la narrativa.", fr: "Fils de tweets, messages WhatsApp, légendes Instagram — tout est pré-écrit avec des données réelles. Copiez. Collez. Changez le récit.", zh: "推文话题串、WhatsApp消息、Instagram文案 — 全部用真实数据预写好。复制。粘贴。改变叙事。", ja: "ツイートスレッド、WhatsAppメッセージ、Instagramキャプション — すべて実データで作成済み。コピー。ペースト。物語を変えよう。", ko: "트윗 스레드, WhatsApp 메시지, Instagram 캡션 — 모두 실제 데이터로 미리 작성됨. 복사. 붙여넣기. 내러티브를 바꿔라.", hi: "ट्वीट थ्रेड, WhatsApp संदेश, Instagram कैप्शन — सभी वास्तविक डेटा के साथ पहले से लिखे गए। कॉपी करें। पेस्ट करें। कथा बदलें।", ar: "سلاسل التغريد، رسائل واتساب، تعليقات إنستغرام — جميعها مكتوبة مسبقاً ببيانات حقيقية. انسخ. الصق. غيّر السرد.", ru: "Треды в твиттере, сообщения WhatsApp, подписи Instagram — всё заранее написано с реальными данными. Копируй. Вставляй. Меняй нарратив." },
  "act.by_country": { en: "BY COUNTRY", pt: "POR PAÍS", es: "POR PAÍS", fr: "PAR PAYS", zh: "按国家", ja: "国別", ko: "국가별", hi: "देश अनुसार", ar: "حسب الدولة", ru: "ПО СТРАНЕ" },
  "act.by_sdg": { en: "BY SDG EQUATION", pt: "POR EQUAÇÃO ODS", es: "POR ECUACIÓN ODS", fr: "PAR ÉQUATION ODD", zh: "按SDG方程", ja: "SDG別", ko: "SDG 방정식별", hi: "एसडीजी समीकरण अनुसार", ar: "حسب معادلة الأهداف", ru: "ПО ЦУР" },
  "act.search_country_ph": { en: "Search country (e.g. Sudan, SSD, Yemen…)", pt: "Buscar país (ex. Sudão, SSD, Iêmen…)", es: "Buscar país (ej. Sudán, SSD, Yemen…)", fr: "Rechercher un pays (ex. Soudan, SSD, Yémen…)", zh: "搜索国家（如苏丹、SSD、也门…）", ja: "国を検索（例: スーダン、SSD、イエメン…）", ko: "국가 검색 (예: 수단, SSD, 예멘…)", hi: "देश खोजें (जैसे सूडान, SSD, यमन…)", ar: "ابحث عن دولة (مثل السودان، SSD، اليمن…)", ru: "Поиск страны (напр. Судан, SSD, Йемен…)" },
  "act.selected": { en: "✓ Selected:", pt: "✓ Selecionado:", es: "✓ Seleccionado:", fr: "✓ Sélectionné:", zh: "✓ 已选择：", ja: "✓ 選択中:", ko: "✓ 선택됨:", hi: "✓ चयनित:", ar: "✓ مختار:", ru: "✓ Выбрано:" },
  "act.people_word": { en: "people", pt: "pessoas", es: "personas", fr: "personnes", zh: "人口", ja: "人", ko: "명", hi: "लोग", ar: "نسمة", ru: "чел." },
  "act.vulnerability_word": { en: "Vulnerability:", pt: "Vulnerabilidade:", es: "Vulnerabilidad:", fr: "Vulnérabilité:", zh: "脆弱性：", ja: "脆弱性:", ko: "취약성:", hi: "भेद्यता:", ar: "الهشاشة:", ru: "Уязвимость:" },
  "act.quick_pick": { en: "Quick pick — worst crises", pt: "Escolha rápida — piores crises", es: "Elección rápida — peores crisis", fr: "Choix rapide — pires crises", zh: "快速选择 — 最严重危机", ja: "クイック選択 — 最悪の危機", ko: "빠른 선택 — 최악의 위기", hi: "त्वरित चुनाव — सबसे खराब संकट", ar: "اختيار سريع — أسوأ الأزمات", ru: "Быстрый выбор — худшие кризисы" },
