  "act.detected": { en: "detected", pt: "detectado", es: "detectado", fr: "détecté", zh: "已检测", ja: "検出", ko: "감지됨", hi: "पहचाना", ar: "تم الكشف", ru: "определён" },
  "act.needs_title": { en: "WHAT THE DATA SAYS IT NEEDS", pt: "O QUE OS DADOS DIZEM QUE FALTA", es: "LO QUE LOS DATOS DICEN QUE FALTA", fr: "CE QUE LES DONNÉES DISENT QU'IL FAUT", zh: "数据说它需要什么", ja: "データが示す必要なもの", ko: "데이터가 말하는 필요", hi: "डेटा क्या कहता है कि चाहिए", ar: "ما تقوله البيانات أنه يحتاج", ru: "ЧТО ГОВОРЯТ ДАННЫЕ" },
  "act.needs_desc": { en: "critical needs identified. These are sorted by severity — how far the country is from acceptable thresholds.", pt: "necessidades críticas identificadas. Ordenadas por severidade — quão longe o país está dos limiares aceitáveis.", es: "necesidades críticas identificadas. Ordenadas por severidad — qué tan lejos está el país de los umbrales aceptables.", fr: "besoins critiques identifiés. Triés par sévérité — à quel point le pays est éloigné des seuils acceptables.", zh: "个关键需求。按严重程度排序——该国距离可接受阈值有多远。", ja: "の重大なニーズ。深刻度順—受け入れ可能な閾値からどれほど遠いか。", ko: "개의 중대한 필요. 심각도순 정렬 — 수용 가능한 임계값에서 얼마나 떨어져 있는가.", hi: "गंभीर जरूरतें पहचानी गईं। गंभीरता के अनुसार क्रमबद्ध — देश स्वीकार्य सीमा से कितना दूर है।", ar: "احتياجات حرجة محددة. مرتبة حسب الخطورة — مدى بُعد الدولة عن العتبات المقبولة.", ru: "критических нужд выявлено. Отсортированы по тяжести — насколько страна далека от приемлемых порогов." },
  "act.severity": { en: "SEVERITY", pt: "SEVERIDADE", es: "SEVERIDAD", fr: "SÉVÉRITÉ", zh: "严重性", ja: "深刻度", ko: "심각도", hi: "गंभीरता", ar: "الخطورة", ru: "ТЯЖЕСТЬ" },
  "act.ai_title": { en: "AI MESSAGE GENERATOR // UNIQUE, VARIED, ANTI-BAN", pt: "GERADOR DE MENSAGENS IA // ÚNICO, VARIADO, ANTI-BAN", es: "GENERADOR DE MENSAJES IA // ÚNICO, VARIADO, ANTI-BAN", fr: "GÉNÉRATEUR DE MESSAGES IA // UNIQUE, VARIÉ, ANTI-BAN", zh: "AI消息生成器 // 独特、多样、防封", ja: "AIメッセージ生成 // ユニーク、多様、BAN対策", ko: "AI 메시지 생성기 // 고유, 다양, 밴 방지", hi: "AI संदेश जनरेटर // अद्वितीय, विविध, बैन-रोधी", ar: "مولد رسائل الذكاء الاصطناعي // فريد، متنوع، مضاد للحظر", ru: "ГЕНЕРАТОР СООБЩЕНИЙ ИИ // УНИКАЛЬНО, РАЗНООБРАЗНО, АНТИ-БАН" },
  "act.ai_desc": { en: "// Generates unique social media messages from real data. Each generation uses random tone + angle + temperature — no two messages are alike. Your API key stays on your device.", pt: "// Gera mensagens únicas para redes sociais a partir de dados reais. Cada geração usa tom + ângulo + temperatura aleatórios — não há duas mensagens iguais. A sua chave API fica no seu dispositivo.", es: "// Genera mensajes únicos de redes sociales a partir de datos reales. Cada generación usa tono + ángulo + temperatura aleatorios — no hay dos mensajes iguales. Tu clave API permanece en tu dispositivo.", fr: "// Génère des messages uniques pour les réseaux sociaux à partir de données réelles. Chaque génération utilise un ton + angle + température aléatoires — pas deux messages pareils. Votre clé API reste sur votre appareil.", zh: "// 从真实数据生成独特的社交媒体消息。每次生成使用随机语气+角度+温度——没有两条消息相同。你的API密钥留在你的设备上。", ja: "// 実データから独自のSNSメッセージを生成。各生成はランダムなトーン+角度+温度を使用 — 同じメッセージは二つとない。APIキーはあなたのデバイスに留まる。", ko: "// 실제 데이터로 고유한 소셜 미디어 메시지 생성. 각 생성은 무작위 톤 + 각도 + 온도 사용 — 같은 메시지는 없음. API 키는 기기에 저장됨.", hi: "// वास्तविक डेटा से अद्वितीय सोशल मीडिया संदेश बनाता है। प्रत्येक जनरेशन यादृच्छिक टोन + कोण + तापमान का उपयोग करता है — कोई दो संदेश समान नहीं। आपकी API कुंजी आपके डिवाइस पर रहती है।", ar: "// يولد رسائل فريدة لوسائل التواصل من بيانات حقيقية. كل توليد يستخدم نبرة + زاوية + حرارة عشوائية — لا رسالتان متشابهتان. مفتاح API يبقى على جهازك.", ru: "// Создаёт уникальные сообщения для соцсетей из реальных данных. Каждая генерация использует случайный тон + угол + температуру — нет двух одинаковых. Ваш API-ключ остаётся на устройстве." },
  "act.connected": { en: "CONNECTED", pt: "CONECTADO", es: "CONECTADO", fr: "CONNECTÉ", zh: "已连接", ja: "接続済み", ko: "연결됨", hi: "जुड़ा हुआ", ar: "متصل", ru: "ПОДКЛЮЧЕНО" },
