  "act.custom_ph": { en: "Optional: custom instructions (e.g. mention the upcoming election, reference specific NGO)", pt: "Opcional: instruções personalizadas (ex. mencionar a eleição, referenciar ONG específica)", es: "Opcional: instrucciones personalizadas (ej. mencionar elecciones, referenciar ONG específica)", fr: "Optionnel: instructions personnalisées (ex. mentionner les élections, citer une ONG précise)", zh: "可选：自定义指令（如提及即将到来的选举、引用特定NGO）", ja: "オプション: カスタム指示（例: 選挙に言及、特定NGOを参照）", ko: "선택: 사용자 지정 지시 (예: 선거 언급, 특정 NGO 참조)", hi: "वैकल्पिक: कस्टम निर्देश (जैसे आगामी चुनाव का उल्लेख, विशिष्ट NGO संदर्भ)", ar: "اختياري: تعليمات مخصصة (مثل ذكر الانتخابات، الإشارة لمنظمة محددة)", ru: "Опц.: пользовательские инструкции (напр. упомянуть выборы, сослаться на НПО)" },
