  "act.ig_tip": { en: "▸ Tip: Use the Country Briefing page (/the-briefing/) to generate a printable image for your post.", pt: "▸ Dica: Use a página de Briefing do País (/the-briefing/) para gerar uma imagem para o seu post.", es: "▸ Consejo: Usa la página de Briefing del País (/the-briefing/) para generar una imagen imprimible para tu post.", fr: "▸ Astuce: Utilisez la page Briefing du Pays (/the-briefing/) pour générer une image imprimable pour votre post.", zh: "▸ 提示：使用国家简报页面(/the-briefing/)为你的帖子生成可打印图片。", ja: "▸ ヒント: 国別ブリーフィングページ(/the-briefing/)で投稿用の印刷可能画像を生成。", ko: "▸ 팁: 국가 브리핑 페이지(/the-briefing/)에서 게시물용 인쇄 이미지를 생성하세요.", hi: "▸ सुझाव: देश ब्रीफिंग पेज(/the-briefing/) का उपयोग करके अपनी पोस्ट के लिए छवि बनाएं।", ar: "▸ نصيحة: استخدم صفحة موجز الدولة (/the-briefing/) لإنشاء صورة قابلة للطباعة لمنشورك.", ru: "▸ Совет: Используйте страницу брифинга страны (/the-briefing/) для создания картинки к посту." },
