  "act.select_prompt": { en: "▒ Select a country or SDG equation above to generate your campaign kit. ▒", pt: "▒ Selecione um país ou equação ODS acima para gerar o seu kit de campanha. ▒", es: "▒ Selecciona un país o ecuación ODS arriba para generar tu kit de campaña. ▒", fr: "▒ Sélectionnez un pays ou une équation ODD ci-dessus pour générer votre kit de campagne. ▒", zh: "▒ 在上方选择一个国家或SDG方程来生成你的活动工具包。▒", ja: "▒ 上記で国またはSDG方程式を選択してキャンペーンキットを生成。▒", ko: "▒ 위에서 국가 또는 SDG 방정식을 선택하여 캠페인 키트를 생성하세요. ▒", hi: "▒ ऊपर एक देश या एसडीजी समीकरण चुनें और अपना अभियान किट बनाएं। ▒", ar: "▒ اختر دولة أو معادلة أهداف أعلاه لإنشاء حزمة حملتك. ▒", ru: "▒ Выберите страну или уравнение ЦУР выше для создания набора активиста. ▒" },
  "act.copy_btn": { en: "[ COPY ]", pt: "[ COPIAR ]", es: "[ COPIAR ]", fr: "[ COPIER ]", zh: "[ 复制 ]", ja: "[ コピー ]", ko: "[ 복사 ]", hi: "[ कॉपी ]", ar: "[ نسخ ]", ru: "[ КОПИРОВАТЬ ]" },
