"fronts.subtitle_extra": {  en: "// The crisis is not distributed evenly. Here is where each front stands.",  pt: "// A crise não é distribuída igualmente. Eis onde cada frente está.",  es: "// La crisis no se distribuye uniformemente. Aquí está dónde está cada frente.",  fr: "// La crise n'est pas répartie uniformément. Voici où en est chaque front.",  zh: "// 危机分布不均。这里是各战线的现状。",  ja: "// 危機は均等に分布していない。各戦線の現状はここにある。",  ko: "// 위기는 균등하게 분포하지 않는다. 각 전선의 현황은 여기 있다.",  hi: "// संकट समान रूप से वितरित नहीं है। यहाँ प्रत्येक मोर्चे की स्थिति है।",  ar: "// الأزمة لا تتوزع بالتساوي. هذا هو موقف كل جبهة.",  ru: "// Кризис распределён неравномерно. Вот где находится каждый фронт.", },
