"registry.sg_5_validations": {  en: "Minimum 5 peer validations required for public visibility",  pt: "Mínimo de 5 validações por pares necessárias para visibilidade pública",  es: "Mínimo 5 validaciones de pares requeridas para visibilidad pública",  fr: "Minimum 5 validations par les pairs requises pour la visibilité publique",  zh: "至少需要5次同行验证才能公开",  ja: "公開には最低5件のピア検証が必要",  ko: "공개를 위해 최소 5회 동료 검증 필요",  hi: "सार्वजनिक दृश्यता के लिए न्यूनतम 5 सहकर्मी सत्यापन आवश्यक",  ar: "خمس تحقيقات من الأقران كحد أدنى للظهور العام",  ru: "Минимум 5 проверок коллег для публичной видимости", },
"registry.sg_cooldown": {  en: "72-hour cooldown between creation and public visibility",  pt: "Período de espera de 72 horas entre criação e visibilidade pública",  es: "Enfriamiento de 72 horas entre creación y visibilidad pública",  fr: "Délai d'attente de 72 heures entre création et visibilité publique",  zh: "创建与公开之间有72小时冷却期",  ja: "作成から公開まで72時間の待機期間",  ko: "생성과 공개 사이 72시간 대기",  hi: "निर्माण और सार्वजनिक दृश्यता के बीच 72 घंटे की राहत",  ar: "فترة تبريد 72 ساعة بين الإنشاء والظهور العام",  ru: "72-часовая пауза между созданием и публичной видимостью", },
"registry.sg_evidence_scoring": {  en: "Evidence quality scoring (primary=3pts, secondary=1pt, testimony=0.5pt)",  pt: "Pontuação de qualidade de evidência (primária=3pts, secundária=1pt, testemunho=0.5pt)",  es: "Puntuación de calidad de evidencia (primaria=3pts, secundaria=1pt, testimonio=0.5pt)",  fr: "Score de qualité des preuves (primaire=3pts, secondaire=1pt, témoignage=0.5pt)",  zh: "证据质量评分（一级=3分，二级=1分，证词=0.5分）",  ja: "証拠品質スコア（一次=3pt、二次=1pt、証言=0.5pt）",  ko: "증거 품질 점수 (1차=3점, 2차=1점, 증언=0.5점)",  hi: "साक्ष्य गुणवत्ता स्कोरिंग (प्राथमिक=3अंक, द्वितीयक=1अंक, गवाही=0.5अंक)",  ar: "تقييم جودة الأدلة (أولي=3نقاط، ثانوي=1نقطة، شهادة=0.5نقطة)",  ru: "Оценка качества доказательств (первичные=3 балла, вторичные=1 балл, показания=0.5 балла)", },
"registry.sg_reputation": {  en: "Reputation-weighted validation — trust is earned through contributions",  pt: "Validação ponderada por reputação — confiança é conquistada através de contribuições",  es: "Validación ponderada por reputación — la confianza se gana con contribuciones",  fr: "Validation pondérée par la réputation — la confiance se gagne par les contributions",  zh: "声誉加权验证——信任通过贡献获得",  ja: "評判重み付け検証—信頼は貢献を通じて得られる",  ko: "평판 가중 검증 — 신뢰는 기여를 통해 획득",  hi: "प्रतिष्ठा-भारित सत्यापन — विश्वास योगदान से अर्जित होता है",  ar: "تحقق مرجح بالسمعة — الثقة تُكتسب من خلال المساهمات",  ru: "Проверка с учётом репутации — доверие зарабатывается вкладом", },
"registry.sg_right_response": {  en: "Mandatory right-of-response field for accused parties",  pt: "Campo de direito de resposta obrigatório para acusados",  es: "Campo de derecho de respuesta obligatorio para acusados",  fr: "Champ de droit de réponse obligatoire pour les parties accusées",  zh: "被指控方必填的答辩权字段",  ja: "被告人の必須の反論権フィールド",  ko: "피고인을 위한 필수 반론권 필드",  hi: "आरोपित पक्षों के लिए अनिवार्य जवाबी-अधिकार क्षेत्र",  ar: "حقل حق الرد الإلزامي للأطراف المتهم",  ru: "Обязательное поле права на ответ для обвиняемых", },
"registry.sg_supermajority": {  en: "67% supermajority required for CONFIRMED status",  pt: "Supermaioria de 67% necessária para status CONFIRMADO",  es: "Supermayoría del 67% requerida para estado CONFIRMADO",  fr: "Supermajorité de 67% requise pour le statut CONFIRMÉ",  zh: "确认状态需要67%绝对多数",  ja: "確認ステータスには67%の超過半数が必要",  ko: "확정 상태에 67% 초과다수 필요",  hi: "पुष्टि स्थिति के लिए 67% बहुमत आवश्यक",  ar: "أغلبية 67% مطلوبة لحالة المؤكد",  ru: "Для статуса ПОДТВЕРЖДЕНО требуется 67% подавляющего большинства", },
