"registry.un_desc": {  en: "Panel of Experts reports, Chapter VII resolutions, sanctions committee designations.",  pt: "Relatórios do Painel de Especialistas, resoluções do Capítulo VII, designações do comitê de sanções.",  es: "Informes del Grupo de Expertos, resoluciones del Capítulo VII, designaciones del comité de sanciones.",  fr: "Rapports du Groupe d'Experts, résolutions du Chapitre VII, désignations du comité des sanctions.",  zh: "专家小组报告、第七章决议、制裁委员会认定。",  ja: "専門家パネル報告、第7章決議、制裁委員会指定。",  ko: "전문가 패널 보고서, 제7장 결의안, 제재 위원회 지정.",  hi: "विशेषज्ञ पैनल रिपोर्ट, अध्याय VII प्रस्ताव, प्रतिबंध समिति नामांकन।",  ar: "تقارير فريق الخبراء، قرارات الفصل السابع، تعيينات لجنة العقوبات.",  ru: "Доклады Группы экспертов, резолюции Главы VII, определения комитета санкций.", },
"registry.un_findings": {  en: "UN Security Council Findings",  pt: "Constatações do Conselho de Segurança da ONU",  es: "Hallazgos del Consejo de Seguridad de la ONU",  fr: "Conclusions du Conseil de Sécurité de l'ONU",  zh: "联合国安理会调查结论",  ja: "国連安全保障理事会の調査結果",  ko: "유엔 안전보장이사회 결론",  hi: "संयुक्त राष्ट्र सुरक्षा परिषद निष्कर्ष",  ar: "نتائج مجلس الأمن التابع للأمم المتحدة",  ru: "Заключения Совета Безопасности ООН", },
"timeline.agri_roi": {  en: "Agricultural R&D has 20× ROI",  pt: "P&D Agrícola tem 20× ROI",  es: "I+D Agrícola tiene 20× ROI",  fr: "R&D Agricole a 20× ROI",  zh: "农业研发有20倍投资回报",  ja: "農業R&Dは20倍のROI",  ko: "농업 R&D는 20배 ROI",  hi: "कृषि आर एंड डी का 20गुना ROI",  ar: "البحث الزراعي له عائد 20×",  ru: "Сельхоз НИОКР дают 20× ОИВ", },
"timeline.agri_roi_desc": {  en: "— every $1 invested returns $20. It reaches the fewest people directly but creates climate-resilient crops that feed billions. School Feeding has 10× ROI and breaks the intergenerational cycle of poverty.",  pt: "— cada $1 investido retorna $20. Atinge menos pessoas diretamente, mas cria culturas resilientes ao clima que alimentam bilhões. Alimentação Escolar tem 10× ROI e quebra o ciclo intergeracional da pobreza.",  es: "— cada $1 invertido devuelve $20. Alcanza a menos personas directamente pero crea cultivos resilientes al clima que alimentan a miles de millones. Alimentación Escolar tiene 10× ROI y rompe el ciclo intergeneracional de la pobreza.",  fr: "— chaque $1 investi rapporte $20. Il atteint le moins de personnes directement mais crée des cultures résilientes au climat qui nourrissent des milliards. L'Alimentation Scolaire a 10× ROI et brise le cycle intergénérationnel de la pauvreté.",  zh: "— 每投入$1回报$20。直接惠及人数最少，但创造气候适应性作物养活数十亿人。学校供餐有10倍投资回报并打破贫困的代际循环。",  ja: "— 投資$1につき$20のリターン。直接的には少数の人にしか届かないが、気候変動に強い作物を生み出し数十億人を養う。学校給食は10倍のROIを持ち、貧困の世代間連鎖を断ち切る。",  ko: "— 투자 $1당 $20 수익. 직접 도달하는 사람은 적지만 기후 변화에 강한 작물을 만들어 수십억 명을 먹인다. 학교 급식은 10배 ROI를 가지며 빈곤의 세대 간 순환을 끊는다.",  hi: "— प्रत्येक $1 निवेश पर $20 रिटर्न। यह सीधे तौर पर सबसे कम लोगों तक पहुँचता है लेकिन जलवायु-सहिष्णु फसलें बनाता है जो अरबों को खिलाती हैं। स्कूल भोजन का 10गुना ROI है और यह गरीबी के अंतरपीढ़ी चक्र को तोड़ता है।",  ar: "— كل دولار $1 مستثمر يعيد $20. يصل لأقل عدد من الناس مباشرة لكنه يخلق محاصيل مقاومة للمناخ تطعم المليارات. التغذية المدرسية لها عائد 10× وتكسر دورة الفقر بين الأجيال.",  ru: "— каждый вложенный $1 приносит $20. Прямо охватывает меньше всего людей, но создаёт климатоустойчивые культуры, кормящие миллиарды. Школьное питание даёт 10× ОИВ и разрывает межпоколенческий цикл бедности.", },
"timeline.ambitious_saves": {  en: "The Ambitious scenario saves",  pt: "O cenário Ambicioso salva",  es: "El escenario Ambicioso salva",  fr: "Le scénario Ambitieux sauve",  zh: "雄心方案拯救",  ja: "野心的シナリオは救う",  ko: "야심 찬 시나리오가 구한다",  hi: "महत्वाकांक्षी परिदृश्य बचाता है",  ar: "السيناريو الطموح ينقذ",  ru: "Амбициозный сценарий спасает", },
"timeline.cheaper_missile": {  en: "cheaper than a single missile.",  pt: "mais barato que um único míssil.",  es: "más barato que un solo misil.",  fr: "moins cher qu'un seul missile.",  zh: "比一枚导弹还便宜。",  ja: "ミサイル1発より安い。",  ko: "미사일 한 발보다 저렴하다.",  hi: "एक मिसाइल से सस्ता।",  ar: "أرخص من صاروخ واحد.",  ru: "дешевле одной ракеты.", },
"timeline.life_year": {  en: "life/year",  pt: "vida/ano",  es: "vida/año",  fr: "vie/an",  zh: "生命/年",  ja: "命/年",  ko: "생명/년",  hi: "जीवन/वर्ष",  ar: "حياة/سنة",  ru: "жизнь/год", },
"timeline.lives_10yr": {  en: "lives over 10 years for $93B/yr.",  pt: "vidas em 10 anos por $93B/ano.",  es: "vidas en 10 años por $93B/año.",  fr: "vies sur 10 ans pour $93Md/an.",  zh: "生命，10年内每年$93B。",  ja: "人の命を10年間で年$93B。",  ko: "생명을 10년간 연 $93B로.",  hi: "जानें 10 वर्षों में वर्ष $93B में।",  ar: "أرواحًا خلال 10 سنوات مقابل $93مليار/سنة.",  ru: "жизней за 10 лет при $93МЛРД/год.", },
"timeline.lives_in_balance": {  en: "lives hang in the balance. This is what happens if we act — and what happens if we don't.",  pt: "vidas estão em jogo. Eis o que acontece se agirmos — e se não agirmos.",  es: "vidas penden de un hilo. Esto es lo que pasa si actuamos — y si no.",  fr: "vies sont en jeu. Voici ce qui se passe si nous agissons — et si nous n'agissons pas.",  zh: "生命悬于一线。这是我们行动的后果——以及不行动的后果。",  ja: "人の命がかかっている。行動すれば—しなければどうなるか。",  ko: "생명이 달려있다. 우리가 행동하면 — 하지 않으면 어떻게 되는가.",  hi: "जानें दांव पर हैं। हम कार्रवाई करें तो क्या होगा — नहीं तो क्या।",  ar: "أرواح معلقة في الميزان. هذا ما يحدث إذا تصرفنا — وإذا لم نفعل.",  ru: "жизней висят на волоске. Вот что будет, если мы действуем — и если нет.", },
