  "signal.alert_desc1": {  en: "don't just pin countries — pin",  pt: "não fixe apenas países — fixe",  es: "no solo fijes países — fija",  fr: "n'épinglez pas seulement des pays — épinglez",  zh: "不仅固定国家——固定",  ja: "国だけでなく—固定するのは",  ko: "국가만 고정하지 말고 — 고정하세요",  hi: "केवल देशों को पिन नहीं — पिन करें",  ar: "لا تثبّت الدول فقط — ثبّت",  ru: "закрепляйте не только страны — закрепляйте",  },
  "signal.alert_desc2": {  en: "scan all 200 countries against any metric threshold. water, health, energy, education, climate, inequality — all 19 dimensions.",  pt: "verifique todos os 200 países contra qualquer limiar de métrica. água, saúde, energia, educação, clima, desigualdade — todas as 19 dimensões.",  es: "escanea los 200 países contra cualquier umbral de métrica. agua, salud, energía, educación, clima, desigualdad — las 19 dimensiones.",  fr: "scannez les 200 pays selon n'importe quel seuil. eau, santé, énergie, éducation, climat, inégalité — les 19 dimensions.",  zh: "扫描全部200个国家对照任何指标阈值。水、健康、能源、教育、气候、不平等——全部19个维度。",  ja: "全200カ国をあらゆる指標の閾値でスキャン。水、健康、エネルギー、教育、気候、不平等—全19次元。",  ko: "모든 200개국을 모든 지표 임계값으로 스캔. 물, 보건, 에너지, 교육, 기후, 불평등 — 전 19차원.",  hi: "किसी भी मापदंड सीमा के विरुद्ध सभी 200 देशों को स्कैन करें। पानी, स्वास्थ्य, ऊर्जा, शिक्षा, जलवायु, असमानता — सभी 19 आयाम।",  ar: "افحص جميع 200 دولة مقابل أي حد مقياس. الماء، الصحة، الطاقة، التعليم، المناخ، عدم المساواة — كل الأبعاد الـ19.",  ru: "сканируйте все 200 стран по любому порогу показателя. вода, здоровье, энергия, образование, климат, неравенство — все 19 измерений.",  },
