  "signal.disarm": {  en: "DISARM",  pt: "DESARMAR",  es: "DESARMAR",  fr: "DÉSARMER",  zh: "取消",  ja: "解除",  ko: "해제",  hi: "निष्क्रिय",  ar: "إلغاء التسليح",  ru: "ОТКЛЮЧИТЬ",  },
  "signal.dossier": {  en: "DOSSIER",  pt: "DOSSIÊ",  es: "EXPEDIENTE",  fr: "DOSSIER",  zh: "档案",  ja: "件",  ko: "사건",  hi: "डॉसियर",  ar: "الملف",  ru: "ДОСЬЕ",  },
  "signal.empty_desc1": {  en: "No countries pinned. Your watchlist is the early-warning layer — pin crisis zones to track conditions at a glance.",  pt: "Nenhum país fixado. Sua observação é a camada de alerta precoce — fixe zonas de crise para acompanhar condições num relance.",  es: "Sin países fijados. Tu lista de vigilancia es la capa de alerta temprana — fija zonas de crisis para seguir las condiciones de un vistazo.",  fr: "Aucun pays épinglé. Votre liste est la couche d'alerte précoce — épinglez les zones de crise pour suivre les conditions d'un coup d'œil.",  zh: "没有固定国家。你的观察列表是预警层——固定危机区域以一目了然地追踪状况。",  ja: "ピン留めされた国はありません。ウォッチリストは早期警告レイヤー—危機地域をピン留めして状況を一目で把握。",  ko: "고정된 국가 없음. 관심 목록은 조기 경보 계층 — 위기 지역을 고정하여 한눈에 파악하세요.",  hi: "कोई देश पिन नहीं किया गया। आपकी वॉचलिस्ट प्रारंभिक-चेतावनी परत है — स्थितियों पर नज़र रखने के लिए संकट क्षेत्रों को पिन करें।",  ar: "لا دول مثبتة. قائمتك هي طبقة الإنذار المبكر — ثبّت مناطق الأزمات لتتبع الظروف بنظرة سريعة.",  ru: "Нет закреплённых стран. Ваш список — слой раннего предупреждения — закрепите зоны кризиса для отслеживания состояния с первого взгляда.",  },
  "signal.empty_desc2": {  en: "↓ Use the console below to add countries. Quick-add buttons for all 22 WFP hotspots are standing by.",  pt: "↓ Use o console abaixo para adicionar países. Botões de adição rápida para todos os 22 hotspots da WFP estão prontos.",  es: "↓ Usa la consola de abajo para añadir países. Botones de adición rápida para los 22 puntos críticos del WFP están listos.",  fr: "↓ Utilisez la console ci-dessous pour ajouter des pays. Les boutons d'ajout rapide pour les 22 points chauds du PAM sont prêts.",  zh: "↓ 使用下方控制台添加国家。所有22个WFP热点的快速添加按钮已就绪。",  ja: "↓ 下のコンソールを使って国を追加。全22のWFPホットスポットのクイック追加ボタンが待機中。",  ko: "↓ 아래 콘솔을 사용하여 국가를 추가하세요. 모든 22개 WFP 핫스팟 빠른 추가 버튼이 대기 중입니다.",  hi: "↓ नीचे कंसोल का उपयोग करके देश जोड़ें। सभी 22 WFP हॉटस्पॉट के लिए त्वरित-जोड़ें बटन तैयार हैं।",  ar: "↓ استخدم وحدة التحكم أدناه لإضافة دول. أزرار الإضافة السريعة لجميع 22 نقطة ساخنة لـ WFP جاهزة.",  ru: "↓ Используйте консоль ниже для добавления стран. Кнопки быстрого добавления всех 22 очагов ВПП готовы.",  },
  "signal.export_json": {  en: "EXPORT JSON",  pt: "EXPORTAR JSON",  es: "EXPORTAR JSON",  fr: "EXPORTER JSON",  zh: "导出JSON",  ja: "JSON書き出し",  ko: "JSON 내보내기",  hi: "JSON निर्यात",  ar: "تصدير JSON",  ru: "ЭКСПОРТ JSON",  },
