  "diff.severity": { en: "Severity:", pt: "Severidade:", es: "Severidad:", fr: "Sévérité:", zh: "严重性：", ja: "重大度：", ko: "심각도:", hi: "गंभीरता:", ar: "الخطورة:", ru: "Серьёзность:" },
  "diff.list_snapshots": { en: "List snapshots:", pt: "Listar snapshots:", es: "Listar snapshots:", fr: "Lister snapshots:", zh: "列出快照：", ja: "スナップショット一覧：", ko: "스냅샷 목록:", hi: "स्नैपशॉट सूची:", ar: "قائمة اللقطات:", ru: "Список снимков:" },

