  "flow.click_trace": { en: "Click to trace flows", pt: "Clique para rastrear fluxos", es: "Clic para rastrear flujos", fr: "Cliquez pour tracer les flux", zh: "点击追踪流动", ja: "クリックして流動を追跡", ko: "클릭하여 흐름 추적", hi: "प्रवाह ट्रैक करने के लिए क्लिक करें", ar: "انقر لتتبع التدفقات", ru: "Нажмите для отслеживания потоков" },
