  "missions.no_missions": { en: "No missions available for current persona. Select a different persona to see relevant missions.", pt: "Nenhuma missão disponível para o persona atual. Selecione um persona diferente para ver missões relevantes.", es: "No hay misiones disponibles para el persona actual. Selecciona un persona diferente para ver misiones relevantes.", fr: "Aucune mission disponible pour le persona actuel. Sélectionnez un persona différent pour voir les missions pertinentes.", zh: "当前角色没有可用任务。选择不同的角色以查看相关任务。", ja: "現在のペルソナに利用可能なミッションがありません。関連ミッションを見るには別のペルソナを選択してください。", ko: "현재 페르소나에 사용 가능한 미션이 없습니다. 관련 미션을 보려면 다른 페르소나를 선택하세요.", hi: "वर्तमान पर्सोना के लिए कोई मिशन उपलब्ध नहीं है। प्रासंगिक मिशन देखने के लिए एक अलग पर्सोना चुनें।", ar: "لا توجد مهام متاحة للشخصية الحالية. اختر شخصية مختلفة لرؤية المهام ذات الصلة.", ru: "Нет доступных миссий для текущей персоны. Выберите другую персону, чтобы увидеть соответствующие миссии.", fa: "هیچ مأموریتی برای پرسونای فعلی موجود نیست. مأموریت‌های مرتبط را ببینید پرسونای دیگری را انتخاب کنید.", ur: "موجودہ شخصا کے لیے کوئی ماموریت دستیاب نہیں ہے۔ متعلقہ ماموریت دیکھنے کے لیے ایک اور شخصا منتخب کریں۔" },
  "missions.steps": { en: "steps", pt: "etapas", es: "pasos", fr: "étapes", zh: "步骤", ja: "ステップ", ko: "단계", hi: "चरण", ar: "خطوات", ru: "шагов", fa: "مراحل", ur: "مراحل" },
