  "playbooks.status": { en: "Status", pt: "Status", es: "Estado", fr: "Statut", zh: "状态", ja: "ステータス", ko: "상태", hi: "स्थिति", ar: "الحالة", ru: "Статус", fa: "وضعیت", ur: "حیثیت" },
