  "import.no_token": { en: "✗ No token provided", pt: "✗ Nenhum token fornecido", es: "✗ No se proporcionó token", fr: "✗ Aucun token fourni", zh: "✗ 未提供令牌", ja: "✗ トークンが提供されていません", ko: "✗ 토큰이 제공되지 않았습니다", hi: "✗ कोई टोकन नहीं दिया गया", ar: "✗ لم يتم توفير رمز", ru: "✗ Токен не предоставлен", fa: "✗ توکن ارائه نشد", ur: "✗ کوئی ٹوکن نہیں دیا گیا" },
  "import.success": { en: "✓ Progress imported successfully", pt: "✓ Progresso importado com sucesso", es: "✓ Progreso importado con éxito", fr: "✓ Progrès importé avec succès", zh: "✓ 进度导入成功", ja: "✓ 進捗をインポートしました", ko: "✓ 진행률을 가져왔습니다", hi: "✓ प्रगति सफलतापूर्वक आयात की गई", ar: "✓ تم استيراد التقدم بنجاح", ru: "✓ Прогресс успешно импортирован", fa: "✓ پیشرفت با موفقیت وارد شد", ur: "✓ پیشرفت کامیابی سے درآمد کی گئی" },
