  /* Rotation status messages */
  "rotation.success": { en: "✓ Key rotated successfully. Old key remains valid for 30 days.", pt: "✓ Chave girada com sucesso. Chave antiga permanece válida por 30 dias.", es: "✓ Clave rotada con éxito. La clave antigua permanece válida por 30 días.", fr: "✓ Clé tournée avec succès. L'ancienne clé reste valide pendant 30 jours.", zh: "✓ 密钥轮换成功。旧密钥在30天内仍然有效。", ja: "✓ キーのローテーションが成功しました。旧キーは30日間有効です。", ko: "✓ 키 회전 성공. 이전 키는 30일 동안 유효합니다.", hi: "✓ कुंजी सफलतापूर्वक घुमाई गई। पुरानी कुंजी 30 दिनों तक मान्य रहेगी।", ar: "✓ تم تدوير المفتاح بنجاح. المفتاح القديم يبقى صالحًا لمدة 30 يومًا.", ru: "✓ Ключ успешно сменен. Старый ключ остается действительным в течение 30 дней.", fa: "✓ کلید با موفقیت چرخش یافت. کلید قدیمی ۳۰ روز دیگر معتبر باقی می‌ماند.", ur: "✓ کلید کامیابی سے گھمائی گئی۔ پرانی کلید ۳۰ دن تک درست رہے گی۔" },
